?><html><head><meta charset="UTF-8"><style>body{font-family:Arial;color:#172033}table{border-collapse:collapse;width:100%}th{background:#fabd02;color:#000000;padding:10px;border:1px solid #cbd5e1}td{padding:9px;border:1px solid #cbd5e1;vertical-align:top}.iso{background:#0f172a;color:white;font-size:19px;font-weight:bold}.quality{background:#fff8d6;color:#000000;font-weight:bold}.meta{background:#f8fafc;color:#475569}.amount{text-align:right}.pending{background:#fef3c7}.submitted{background:#e0f2fe}.retained{background:#dcfce7}.dismissed{background:#f1f5f9}</style></head><body><table><tr><td colspan="7" class="iso">BANAMUR INDUSTRIES · CONTESTATIONS DE PRIX FEB</td><td colspan="3" class="quality">DOCUMENT MAÎTRISÉ · ISO 9001</td></tr><tr class="meta"><td><b>Référence</b></td><td colspan="2"><?=htmlspecialchars($documentId)?></td><td><b>Code qualité</b></td><td colspan="2">ACH-FEB-CONTEST-01</td><td><b>Édition</b></td><td colspan="3"><?=date('d/m/Y à H:i')?></td></tr><tr class="meta"><td><b>Filtre</b></td><td colspan="2"><?=htmlspecialchars($statusLabel)?></td><td><b>Recherche</b></td><td colspan="3"><?=htmlspecialchars($q!==''?$q:'Aucune')?></td><td><b>Résultats</b></td><td colspan="2"><?=count($rows)?></td></tr><tr><th>Statut</th><th>Catégorie</th><th>Besoin</th><th>Chantier</th><th>Quantité</th><th>Planning</th><th>Fournisseur proposé</th><th>Montant total</th><th>Prix unitaire</th><th>Date de transmission</th></tr><?php foreach($rows as $row):$s=(string)($row['status']??'');?><tr class="<?=htmlspecialchars($s)?>"><td><?=htmlspecialchars($labels[$s]??$s)?></td><td><?=htmlspecialchars((string)($row['category']??''))?></td><td><?=htmlspecialchars((string)(($row['designation']??'')?:($row['quote_title']??'')))?></td><td><?=htmlspecialchars((string)($row['chantier_label']??''))?></td><td><?=number_format((float)($row['quantity']??0),2,',',' ')?></td><td><?=htmlspecialchars((string)($row['planned_start_date']??''))?> au <?=htmlspecialchars((string)($row['planned_end_date']??''))?></td><td><?=htmlspecialchars((string)($row['proposed_supplier_name']??''))?></td><td class="amount"><?=number_format((float)($row['proposed_total_amount']??0),0,',',' ')?> FCFA</td><td class="amount"><?=number_format((float)($row['proposed_unit_price']??0),2,',',' ')?> FCFA</td><td><?=!empty($row['submitted_at'])?date('d/m/Y H:i',strtotime((string)$row['submitted_at'])):''?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="10">Aucun résultat pour ce filtre.</td></tr><?php endif;?><tr class="meta"><td colspan="10"><b>Confidentialité :</b> le demandeur et le prix initial restent masqués. Document généré pour l’utilisateur connecté.</td></tr></table></body></html>
